      "rawText": "十余年间，中国新能源汽车产业完成上半场突围，以“拼电量、拼补能”为核心的硬件竞赛，推动我国产销量多年居全球第一。如今行业迈入智能化下半场，竞争重心转向算力水平。当前主流车型续航普遍超600公里，而智能化功能需强大算力，L4级别车型算力需求突破2000TOPS。国内车企和芯片企业构建协同生态，形成链式发展格局。不过要警惕盲目堆砌算力和重硬件轻算法的误区，算力竞争应提升有效算力。从“电量”到“算力”比拼，是产业技术迭代，未来国产车载算力产业链成熟将引领全球变革。 (AI生成)",
